using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using System.Windows;
using System.Windows.Media;

namespace QiDesk {
public static class FileFeatureTests {
    public static void Run(string root,Action<bool,string> check){
        check(IgnoreRuleInput.Split("*.tmp，*.log;*.bak  *.cache\n*.old").SequenceEqual(new[]{"*.tmp","*.log","*.bak","*.cache","*.old"}),"ignore input separates Chinese and English punctuation and whitespace into individual rules");
        var store=new Store(Path.Combine(root,"file-features"));string folder=Path.Combine(root,"workspace");Directory.CreateDirectory(folder);string normal=Path.Combine(folder,"report.txt"),generated=Path.Combine(folder,"ChatGPT-output.txt"),temp=Path.Combine(folder,"build.tmp");File.WriteAllText(normal,"normal");File.WriteAllText(generated,"generated");File.WriteAllText(temp,"tmp");var a=store.Data.Groups[0];var b=store.Data.Groups[1];a.Items.AddRange(new[]{normal,generated,temp});b.Items.Add(normal);
        a.IgnoreRules.Add(new IgnoreRule(){Pattern="REPORT.*"});check(!store.Items(a,"").Contains(normal)&&store.Items(b,"").Contains(normal),"local ignore is case insensitive and confined to its group");a.IgnoreRules.Clear();store.Data.IgnoreRules.Add(new IgnoreRule(){Pattern="*.txt"});check(!store.Items(a,"").Contains(normal)&&!store.Items(b,"").Contains(normal)&&store.Items(a,"").Contains(temp),"global filename wildcard applies to all groups without hiding other extensions");store.Data.IgnoreRules.Clear();check(store.Items(a,"").Contains(normal)&&a.Items.Contains(normal)&&File.Exists(normal),"restoring ignored file keeps original membership and physical file");
        a.IgnoreRules.Add(new IgnoreRule(){Kind="路径",Pattern=normal});store.Save();var loaded=new Store(store.Root);check(loaded.Data.Groups[0].IgnoreRules.Count==1&&!loaded.Items(loaded.Data.Groups[0],"").Contains(normal),"local exact-file ignore persists across restart");store.Checkpoint();store.Data.IgnoreRules.Add(new IgnoreRule(){Pattern="*.tmp"});store.Save();check(store.Undo()&&store.Items(store.Data.Groups[0],"").Contains(temp),"ignore changes can be undone");
        store.Data.WorkFolders.Add(folder);check(store.Ignored(generated,null)&&!store.Ignored(normal,null)&&!store.Ignored(temp,null),"registered workspace auto hides generated prefixes but preserves ordinary and temporary files");string neighbor=folder+"-other";Directory.CreateDirectory(neighbor);string other=Path.Combine(neighbor,"ChatGPT-output.txt");File.WriteAllText(other,"other");check(!store.Ignored(other,null),"workspace boundary excludes similarly named sibling directories");store.Data.WorkIgnoreCaches=true;check(store.Ignored(temp,null),"cache and temporary hiding requires explicit preference");store.Data.WorkAutoIgnore=false;check(!store.Ignored(generated,null)&&!store.Ignored(temp,null),"disabling workspace auto hide restores generated and temporary files");store.Data.WorkAutoIgnore=true;string generatedFolder=Path.Combine(folder,"generated-build");Directory.CreateDirectory(generatedFolder);string nested=Path.Combine(generatedFolder,"report.txt");File.WriteAllText(nested,"nested");check(store.Ignored(nested,null),"generated directory descendants inherit auto hide");
        var portal=new Group(){Folder=folder};check(!store.Items(portal,"").Contains(generated)&&store.Items(portal,"").Contains(normal),"folder portals use the same global and workspace ignore policy");var detection=WorkDetection.Scan(store.Data);check(detection.Any(x=>x.Path==generated)&&detection.All(x=>x.Path!=normal)&&File.ReadAllText(generated)=="generated","workspace scan provides candidates without altering contents");
        var zoom=new Group(){ViewMode="详细信息",IconSize=34};FilePresentation.Zoom(zoom,1);check(zoom.ViewMode=="列表","Ctrl wheel increases detail view to list view");FilePresentation.Zoom(zoom,1);check(zoom.ViewMode=="图标"&&zoom.IconSize==20,"Ctrl wheel advances from list to small icons");for(int i=0;i<50;i++)FilePresentation.Zoom(zoom,1);check(zoom.IconSize==96,"icon zoom stops at maximum size");for(int i=0;i<50;i++)FilePresentation.Zoom(zoom,-1);check(zoom.ViewMode=="详细信息","Ctrl wheel decreases through icons and list into details");
        check(FilePresentation.DisplayName(normal,false)=="report"&&FilePresentation.DisplayName(normal,true)=="report.txt"&&FilePresentation.DisplayName(folder,false)=="workspace"&&FilePresentation.DisplayName(Path.Combine(folder,".gitignore"),false)==".gitignore","extension preference changes labels without changing paths or dotfiles");
        check(FilePresentation.IsApplication(Path.Combine(folder,"Example.lnk"))&&FilePresentation.IsApplication(Path.Combine(folder,"Example.exe"))&&!FilePresentation.IsApplication(normal),"application shortcuts use the rounded app icon treatment");
        var kindState=new State();var folderPanel=new Group(){Folder=folder};kindState.Groups.Add(folderPanel);Store.Validate(kindState);check(folderPanel.Kind=="文件夹"&&folderPanel.Folders.Count==1&&folderPanel.Folders[0]==folder,"a legacy single-folder mapping upgrades into a folder-tab panel");
        check(FilePresentation.MatchesKind(normal,"工作")&&FilePresentation.MatchesKind(Path.Combine(root,"app.lnk"),"应用")&&!FilePresentation.MatchesKind(Path.Combine(root,"app.lnk"),"工作")&&!FilePresentation.MatchesKind(folder,"工作"),"type panels split work files from applications and skip folders");
        var tabbed=new Group(){Name="收件箱",Kind="普通",FolderIndex=0,Folders=new List<string>{folder},Items=new List<string>{normal}};var tabState=new State();tabState.Groups.Add(tabbed);Store.Validate(tabState);check(tabbed.Kind=="普通"&&tabbed.Folders.Count==1&&tabbed.Items.Contains(normal),"folder tabs preserve ordinary group contents");
        check(FilePresentation.MatchesKind(Path.Combine(root,"photo.png"),"图片")&&!FilePresentation.MatchesKind(Path.Combine(root,"photo.png"),"文档")&&FilePresentation.MatchesKind(normal,"文档"),"work panel image and document tabs filter separately");
        var legacyPicture=Path.Combine(folder,"photo.png");File.WriteAllText(legacyPicture,"image");var legacy=new State(){Version=5};legacy.Groups.Add(new Group(){Name="图片与工作文档",Kind="工作",Items=new List<string>{normal,legacyPicture}});Store.Validate(legacy);var documentGroup=legacy.Groups.First(g=>g.Name=="文档");var pictureGroup=legacy.Groups.First(g=>g.Name=="图片");check(legacy.Version==8&&documentGroup.Items.Contains(normal)&&pictureGroup.Items.Contains(legacyPicture)&&pictureGroup.HostGroupId==documentGroup.Id,"legacy work panel becomes ordinary document and picture sections with memberships preserved");check(!store.ItemsAt(a,"",a.Folder).Contains(legacyPicture),"unassigned files do not appear in an ordinary section");check(FluentIcons.Icon(folder,"Fluent 线条",Colors.SteelBlue)!=null&&FluentIcons.Icon(normal,"Fluent 填充",Colors.SteelBlue)!=null,"bundled open source icon skins load their vector resources");
        var panelStore=new Store(Path.Combine(root,"default-panels"));panelStore.Data=new State();var panelController=new Controller(panelStore);panelController.GenerateDefaultPanels();check(panelStore.Data.Groups.Count==4&&panelStore.Data.Groups.Count(g=>String.IsNullOrEmpty(g.HostGroupId))==3&&panelStore.Data.Groups.Any(g=>g.Name=="文档"&&g.Width>=560)&&panelStore.Data.Groups.Any(g=>g.Name=="应用"&&g.Height>=300&&g.IconSize==30)&&panelStore.Data.Groups.Any(g=>g.Name=="图片"&&!String.IsNullOrEmpty(g.HostGroupId)),"default panels give applications room for six icons and preserve document and picture tabs");var savedPanels=panelStore.Data.Groups.Select(g=>g.Id+":"+g.X+":"+g.Y+":"+g.Width+":"+g.Height).ToArray();panelStore.Data.Groups.First(g=>g.Name=="文档").X=42;panelController.GenerateDefaultPanels();check(panelStore.Data.Groups.Count==4&&panelStore.Data.Groups.Select(g=>g.Id+":"+g.X+":"+g.Y+":"+g.Width+":"+g.Height).SequenceEqual(savedPanels),"regenerating default panels restores layout without duplicating sections");
        string managed=Path.Combine(root,"managed","shortcut.lnk"),original=Path.Combine(root,"restored-shortcut.lnk");Directory.CreateDirectory(Path.GetDirectoryName(managed));File.WriteAllText(managed,"shortcut");var managedState=new State();managedState.ManagedDesktopItems[managed]=original;check(DesktopOrganization.Release(managedState,managed)==original&&File.Exists(original)&&!File.Exists(managed)&&managedState.ManagedDesktopItems.Count==0,"managed desktop item restores its original location when removed from a section");
        File.WriteAllText(managed,"shortcut-again");string hidden=Path.Combine(root,"hidden.txt");File.WriteAllText(hidden,"hidden");File.SetAttributes(hidden,File.GetAttributes(hidden)|FileAttributes.Hidden);string restoreRoot=Path.Combine(root,"restore-desktop");Directory.CreateDirectory(restoreRoot);var restoreStore=new Store(restoreRoot,false);restoreStore.Data=new State();restoreStore.Data.Groups.Add(new Group(){Items=new List<string>{managed,hidden}});restoreStore.Data.ManagedDesktopItems[managed]=original;File.Delete(original);restoreStore.Data.HiddenDesktopItems.Add(hidden);restoreStore.DesktopActive=true;restoreStore.RestoreDesktop();check(!restoreStore.DesktopActive&&File.Exists(original)&&!File.Exists(managed)&&restoreStore.Data.Groups[0].Items.Contains(original)&&restoreStore.Data.ManagedDesktopItems.Count==0&&(File.GetAttributes(hidden)&FileAttributes.Hidden)==0,"stopping desktop mode restores moved and hidden icons while retaining section membership");
        string hiddenFile=Path.Combine(root,"hidden-restore.txt");File.WriteAllText(hiddenFile,"x");File.SetAttributes(hiddenFile,File.GetAttributes(hiddenFile)|FileAttributes.Hidden);var hiddenState=new State();hiddenState.HiddenDesktopItems.Add(hiddenFile);DesktopOrganization.Restore(hiddenState);check(!Functions.IsHidden(hiddenFile)&&hiddenState.HiddenDesktopItems.Count==0,"stopping the desktop clears the hidden attribute and its recovery record");
        check(Functions.SetHidden(hiddenFile,true)&&Functions.IsHidden(hiddenFile)&&Functions.SetHidden(hiddenFile,false)&&!Functions.IsHidden(hiddenFile),"shared file-attribute helper toggles hidden state and reports real changes");
        var old=Store.Json.Deserialize<State>("{\"Version\":1,\"Groups\":[],\"Rules\":[],\"PortalNavigate\":true,\"RollupOnDoubleClick\":true}");Store.Validate(old);check(old.Version==8&&old.PortalNavigate&&!old.HideOriginalIcons&&!old.AutoRules&&!old.RollupOnDoubleClick&&old.WorkAutoIgnore&&old.McpEnabled,"old configuration restores native desktop interaction and leaves loose icons unorganized by default");var transparent=new Group(){BackgroundOpacity=0};var data=new State();data.Groups.Add(transparent);Store.Validate(data);check(transparent.BackgroundOpacity==0&&transparent.IconSize>=20,"transparent background survives configuration validation");check(FilePresentation.FolderName(folder)=="workspace"&&!FilePresentation.Detail(normal).Contains(folder),"file labels and details omit physical directory paths");
        var c=new Controller(store);var result=(System.Collections.IEnumerable)McpBridge.Execute(c,Request("qidesk_list_groups"));check(result.Cast<object>().Count()==4,"MCP group listing reads current application state");McpBridge.Execute(c,Request("qidesk_add_ignore","pattern","*.txt","groupId",store.Data.Groups[1].Id));check(store.Data.Groups[1].IgnoreRules.Count==1&&store.Data.IgnoreRules.Count==0,"MCP adding local ignore preserves global scope");string ruleId=store.Data.Groups[1].IgnoreRules[0].Id;McpBridge.Execute(c,Request("qidesk_remove_ignore","ruleId",ruleId,"groupId",store.Data.Groups[1].Id));check(store.Data.Groups[1].IgnoreRules.Count==0,"MCP removing ignore restores local policy");
        var register=Request("qidesk_register_generated","workspaceId","0");((Dictionary<string,object>)register["arguments"])["paths"]=new[]{normal};McpBridge.Execute(c,register);check(store.Data.IgnoreRules.Any(r=>r.Kind=="路径"&&r.Pattern==normal)&&File.Exists(normal),"MCP registration ignores generated file without modifying it");int count=store.Data.IgnoreRules.Count;((Dictionary<string,object>)register["arguments"])["paths"]=new[]{other};bool rejected=false;try{McpBridge.Execute(c,register);}catch{rejected=true;}check(rejected&&store.Data.IgnoreRules.Count==count&&!store.Ignored(other,null),"MCP rejects file registration outside selected workspace without partial mutation");
        int groups=store.Data.Groups.Count;McpBridge.Execute(c,Request("qidesk_create_portal","workspaceId","0","name","AI workspace"));check(store.Data.Groups.Count==groups+1&&store.Data.Groups.Last().Folder==folder&&File.ReadAllText(normal)=="normal","MCP creates same-folder portal without copying files");bool invalid=false;try{IgnoreRule.Validate(new List<IgnoreRule>{new IgnoreRule(){Pattern="../*"}});}catch{invalid=true;}check(invalid,"filename ignore rejects path traversal syntax");
    }
    static Dictionary<string,object> Request(string name,params string[] values){var args=new Dictionary<string,object>();for(int i=0;i<values.Length;i+=2)args[values[i]]=values[i+1];return new Dictionary<string,object>{{"name",name},{"arguments",args}};}
    public static void Native(Controller c,Action<bool,string> check){var group=new Group(){Name="Transparent check",BackgroundOpacity=0,Width=320,Height=240};var w=new FenceWindow(c,group);try{w.Show();w.UpdateLayout();var frame=w.Content as System.Windows.Controls.Border;check(w.Opacity==1&&((SolidColorBrush)frame.Background).Color.A==1&&frame.BorderThickness.Left>=1,"transparent frame keeps text and border opaque with independent background alpha");w.Close();}finally{if(w.IsVisible)w.Close();}}
}
}


